1|// Pre-commit size check: staged files must stay under 5000 tokens.
2|// Tokens = ceil(bytes / 4). Plain Node, no dependencies.
3|import { execFileSync } from 'node:child_process';
4|import { fileURLToPath } from 'node:url';
5|
6|export const MAX_TOKENS = 5000;
7|export const BYTES_PER_TOKEN = 4;
8|
9|// Paths the size check skips. Entries ending in "/" match that directory
10|// anywhere in the path. Entries with "*" match the file name. Other entries
11|// match the full path or the file name. Add a pattern here (and say why in
12|// the commit message) when a file really is generated or third-party.
13|export const IGNORE_PATTERNS = [
14|  // Lockfiles: not authored by agents.
15|  'package-lock.json',
16|  'pnpm-lock.yaml',
17|  'yarn.lock',
18|  'bun.lockb',
19|  'uv.lock',
20|  'poetry.lock',
21|  '*.lock',
22|  // Codegen: generated dirs cover their *.d.ts files too.
23|  '*.generated.*',
24|  '*.gen.*',
25|  'next-env.d.ts',
26|  'generated/',
27|  '__generated__/',
28|  // Build output.
29|  '.next/',
30|  'dist/',
31|  'out/',
32|  'coverage/',
33|  // Processed book data, and all of public/.
34|  'public/',
35|  'data/processed/',
36|  'pipeline/out/',
37|  // Agent and session logs.
38|  'agent-logs/',
39|  'docs/muse-code-sessions/',
40|  // Vendored third-party skills.
41|  '.agents/skills/',
42|];
43|
44|function globToRegExp(glob) {
45|  return new RegExp('^' + glob.split('*').map(escapeRegExp).join('.*') + '$');
46|}
47|
48|function escapeRegExp(text) {
49|  return text.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
50|}
51|
52|function basename(path) {
53|  const index = path.lastIndexOf('/');
54|  return index === -1 ? path : path.slice(index + 1);
55|}
56|
57|export function isIgnored(path) {
58|  const name = basename(path);
59|  for (const pattern of IGNORE_PATTERNS) {
60|    if (pattern.endsWith('/')) {
61|      if (path === pattern.slice(0, -1) || path.startsWith(pattern) || path.includes('/' + pattern)) {
62|        return true;
63|      }
64|    } else if (pattern.includes('*')) {
65|      if (globToRegExp(pattern).test(name)) return true;
66|    } else if (path === pattern || name === pattern || path.endsWith('/' + pattern)) {
67|      return true;
68|    }
69|  }
70|  return false;
71|}
72|
73|export function estimateTokens(bytes) {
74|  return Math.ceil(bytes / BYTES_PER_TOKEN);
75|}
76|
77|// Pure and testable: entries look like { path, bytes, isBinary }.
78|export function findOversized(entries) {
79|  const oversized = [];
80|  for (const entry of entries) {
81|    if (entry.isBinary || isIgnored(entry.path)) continue;
82|    const tokens = estimateTokens(entry.bytes);
83|    if (tokens > MAX_TOKENS) oversized.push({ path: entry.path, bytes: entry.bytes, tokens });
84|  }
85|  return oversized;
86|}
87|
88|export const SPLIT_HELP = `How to split it:
89|- Split by responsibility into small modules, one concern per file, roughly under 300 lines.
90|- Put shared types in their own file.
91|- Move fixtures and test data to fixtures/ or public/.
92|- For TS/JS create a folder with an index.ts that re-exports the pieces so imports stay stable.
93|- For docs split by heading into docs/<topic>/*.md with a short index.
94|- For tests split per behavior.
95|- Never minify or remove comments to sneak under the limit.
96|- If the file really is generated or third-party, add its pattern to the ignore list in this script and explain why in the commit message.`;
97|
98|function stagedPaths() {
99|  const output = execFileSync(
100|    'git',
101|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
102|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
103|  );
104|  const text = output.toString('utf8');
105|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
106|}
107|
108|// Pure and testable: flags from `git diff --numstat -z` output. Each record is
109|// one NUL-terminated "added\tdeleted\tpath" chunk; a rename is a chunk with
110|// an empty path followed by old-name and new-name chunks, keyed on the new.
111|export function parseNumstatZ(text) {
112|  const flags = new Map();
113|  if (text.length === 0) return flags;
114|  const parts = text.split('\0');
115|  for (let i = 0; i < parts.length; i++) {
116|    const chunk = parts[i];
117|    if (chunk === '') continue;
118|    const record = /^(\d+|-)\t(\d+|-)\t([\s\S]*)$/.exec(chunk);
119|    if (!record) continue;
120|    const isBinary = record[1] === '-' && record[2] === '-';
121|    let path = record[3];
122|    if (path === '') {
123|      const renamed = parts[i + 2];
124|      i += 2;
125|      if (renamed === undefined || renamed === '') continue;
126|      path = renamed;
127|    }
128|    flags.set(path, isBinary);
129|  }
130|  return flags;
131|}
132|
133|// Binary flags from git's own numstat: git prints "-\t-\t" for files whose
134|// first 8000 bytes hold a NUL byte, so this reuses that detection.
135|function stagedBinaryFlags() {
136|  const output = execFileSync(
137|    'git',
138|    ['diff', '--cached', '--numstat', '--diff-filter=ACMR', '-z'],
139|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
140|  );
141|  return parseNumstatZ(output.toString('utf8'));
142|}
143|
144|function stagedBlobSize(path) {
145|  const output = execFileSync('git', ['cat-file', '-s', ':' + path], {
146|    encoding: 'utf8',
147|    stdio: ['ignore', 'pipe', 'ignore'],
148|  });
149|  return Number.parseInt(output.trim(), 10);
150|}
151|
152|function main() {
153|  let paths;
154|  let binaryFlags = new Map();
155|  try {
156|    paths = stagedPaths();
157|    binaryFlags = stagedBinaryFlags();
158|  } catch {
159|    console.error('warning: not a git repo, skipping the file-size check');
160|    return 0;
161|  }
162|  const entries = [];
163|  for (const path of paths) {
164|    if (isIgnored(path)) continue;
165|    let bytes;
166|    try {
167|      bytes = stagedBlobSize(path);
168|    } catch {
169|      continue; // Left the index since the diff was read.
170|    }
171|    entries.push({ path, bytes, isBinary: binaryFlags.get(path) === true });
172|  }
173|  const oversized = findOversized(entries);
174|  if (oversized.length === 0) return 0;
175|  console.error(`error: ${oversized.length} staged file(s) over the ${MAX_TOKENS}-token limit (tokens = ceil(bytes/4)):`);
176|  for (const file of oversized) {
177|    console.error(`  ${file.path}: ${file.bytes} bytes, about ${file.tokens} tokens`);
178|  }
179|  console.error('');
180|  console.error(SPLIT_HELP);
181|  return 1;
182|}
183|
184|const invokedAsScript = process.argv[1] === fileURLToPath(import.meta.url);
185|if (invokedAsScript) process.exit(main());

